"""Read-only summary of node channel gaps."""
import json
from pathlib import Path
import re
import stat
import sys


def _reject_constant(value):
    raise ValueError(value)


def _json(data):
    return json.loads(data.decode("utf-8"), parse_constant=_reject_constant)


def _integer(value):
    return type(value) is int


def _files(node, channel):
    pattern = re.compile(rf"{channel}\.([0-9]{{12}})\.jsonl\Z")
    segments = []
    active = None
    for path in node.iterdir():
        match = pattern.fullmatch(path.name)
        if match is None and path.name != channel + ".active.jsonl":
            continue
        if not stat.S_ISREG(path.lstat().st_mode):
            continue
        if match is not None:
            segments.append((int(match.group(1)), path))
        else:
            active = path
    segments.sort(key=lambda pair: pair[0])
    return [path for _, path in segments] + ([active] if active is not None else [])


def _channel(node, channel, bad):
    seqs = []
    for path in _files(node, channel):
        parts = path.read_bytes().split(b"\n")
        for line_number, data in enumerate(parts[:-1], 1):
            try:
                record = _json(data)
            except (ValueError, UnicodeError, RecursionError):
                why = "bad_json"
            else:
                seq = record.get("seq") if isinstance(record, dict) else None
                why = None if _integer(seq) and seq >= 1 else "no_seq"
            if why is None:
                seqs.append(seq)
            else:
                bad.append({"file": path.name, "line": line_number, "why": why})
        if parts[-1]:
            bad.append({"file": path.name, "line": len(parts), "why": "torn"})
    ordered = sorted(seqs)
    distinct = sorted(set(seqs))
    missing = [[a + 1, b - 1] for a, b in zip(distinct, distinct[1:]) if b > a + 1]
    dup = sorted(seq for seq in distinct if ordered.count(seq) >= 2)
    return {"count": len(seqs), "first": ordered[0] if ordered else None,
            "last": ordered[-1] if ordered else None, "missing": missing,
            "dup": dup, "next_seq": None, "unacked": None, "stale_next": None}, distinct


def _state(node, channels, distinct):
    path = node / "state.json"
    try:
        if not stat.S_ISREG(path.lstat().st_mode):
            return True
        value = _json(path.read_bytes())
    except FileNotFoundError:
        return False
    except (OSError, ValueError, UnicodeError, RecursionError):
        return True
    if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
        return True
    invalid = False
    for channel in ("obs", "must"):
        fields = value["channels"].get(channel)
        if (not isinstance(fields, dict)
                or not _integer(fields.get("next_seq"))
                or (channel == "must" and not _integer(fields.get("acked_upto")))):
            invalid = True
            continue
        result = channels[channel]
        result["next_seq"] = fields["next_seq"]
        if channel == "must":
            result["unacked"] = sum(seq > fields["acked_upto"] for seq in distinct[channel])
        if result["last"] is not None:
            result["stale_next"] = fields["next_seq"] != result["last"] + 1
    return invalid


def summarize(node):
    bad = []
    channels = {}
    distinct = {}
    for channel in ("obs", "must"):
        channels[channel], distinct[channel] = _channel(node, channel, bad)
    if _state(node, channels, distinct):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    print(json.dumps(summarize(Path(args[0])), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
